/// The most ids a buffer keeps.
constexpr static const size_t MAX_IDS = 63;

/// The largest buffer: the owner, then for 63 ids in 63 groups a three-byte run head and the id.
constexpr static const size_t MAX_BUFFER = (1 + (MAX_IDS * 4));

/// One world call: the message (`EEMRecord*`), two objects (a player, a group, a unit: their addresses), integers
/// and floats; the operation's answer is the host's return value (an object's address, a fact).
struct EeNetMsgCall {
  uint64_t message;
  uint64_t a;
  uint64_t b;
  int64_t i[14];
  float f[2];
};

/// The C++ host (EEMessage.cpp's `EENetMsgHost`).
using EeNetMsgHostFn = int64_t(*)(uint32_t op, EeNetMsgCall *call);

/// One step of `EEMExchangeResources` (ee/EEMessageExecute.h): whether it applies, the traded resource's amount
/// (`cost`) and the gold's (`amount`).
struct EeNetMsgExchangeStep {
  uint8_t apply;
  int64_t cost;
  int64_t amount;
};

/// One member of a message (see the module comment).
struct EeNetMsgSlot {
  uint8_t *data;
  uint32_t size;
  uint32_t count;
  uint32_t offset;
};

/// Builds one nested input from the bytes at `data`: its `ExportSize`, or 0 when no message has its type.
using EeNetMsgBuildInput = uint32_t(*)(void *context, const uint8_t *data);

/// One engine type: everything the C++ class answered beyond its members.
struct EeNetMsgNeType {
  /// the codec class (`EE_NETMSG_NE_*`), `u32::MAX` for a type the engine does not build
  uint32_t class_id;
  /// the members on the wire (the codec's slots after the header)
  uint32_t wire_fields;
  /// the record's members: the wire's, then the ones that never travel
  uint32_t fields;
  /// the fixed members' bytes (the record's size)
  uint32_t record_size;
  /// `EE_NETMSG_NE_THROTTLE`, `EE_NETMSG_NE_PAUSED`
  uint8_t flags;
  /// the send-to-all-and-wait id's member (`Get/SetSendToAllAndWaitMessageID`), or `EE_NETMSG_NE_NONE`
  uint8_t s2aw_field;
  /// `IsResponse`: the response's type (0: none), this message's member and the response's that must be equal
  uint8_t response_type;
  uint8_t response_mine;
  uint8_t response_theirs;
  /// `GetMessageLabel`: a static C string
  const char *label;
};

/// A record member: its kind (`EE_NETMSG_NE_FIELD_*`), its offset in the record (a string's ordinal) and its size.
struct EeNetMsgNeField {
  uint8_t kind;
  uint32_t offset;
  uint32_t size;
};

/// A record member: its kind (`EE_NETMSG_RECORD_FIELD_*`, NONE past the last member), its offset in the record and
/// its size.
struct EeNetMsgRecordField {
  uint8_t kind;
  uint32_t offset;
  uint32_t size;
};

/// A record type's rules: its send-to-all-and-wait member (0: none) and `IsResponse`'s (the response's type, 0
/// for none; this message's member and the response's, equal as 32-bit integers).
struct EeNetMsgRecordRules {
  uint8_t wait_field;
  uint8_t response_type;
  uint8_t response_mine;
  uint8_t response_theirs;
};

/// A game message type's shape for the capture's sweep: its kind (`EE_NETMSG_SWEEP_*`), the bytes before its variable
/// member with the 4-byte header (a fixed type's whole size), the fixed bytes after a string.
struct EeNetMsgSweepShape {
  uint8_t kind;
  uint32_t prefix;
  uint32_t suffix;
};

/// An engine message type's shape for the capture's sweep (NMNE): the fixed bytes after the header before its strings
/// or its players' inputs, its strings, whether it carries the inputs (all 0 for no engine type).
struct EeNetMsgEngineSweepShape {
  uint32_t fixed;
  uint32_t strings;
  uint8_t inputs;
};

/// One host call: the forwarder's frame (the communications object, the registers) and the values.
struct EeNetSessCall {
  void *frame;
  int64_t v[8];
};

/// The C++ host (EEServer.cpp's `EESessionHost`).
using EeNetSessHostFn = int64_t(*)(uint32_t op, EeNetSessCall *call);

extern "C" {

/// `EEMRecord::Execute` (`framing` 0), `EEMessage::ExecuteSelectionMessage` (1) or `ExecuteMessage` (2): the type's
/// body over a copy of the message's record (64 bytes, written back when the body changed it: no Rust reference lives
/// across the host's calls) and of its list (`list_len` bytes), with the C++ host.
///
/// # Safety
/// `record` points to the record's bytes, `list` to `list_len` bytes (any pointer when 0); the host is EEMessage.cpp's.
void ee_netmsg_execute(EeNetMsgHostFn host,
                       void *message,
                       uint8_t message_type,
                       uint8_t slot,
                       uint8_t fast_id,
                       uint8_t *record,
                       const uint8_t *list,
                       size_t list_len,
                       uint8_t framing);

/// The sweep for the capture: each payload handed to `sink` in order (kind, bytes); no Rust state is borrowed
/// across the calls (the payloads are made first).
///
/// # Safety
/// `sink` is the capture's C++ function.
void ee_netmsg_capture_sweep(void (*sink)(uint8_t kind, const uint8_t *data, size_t size));

uint8_t ee_netmsg_selection_marks_local(uint8_t is_server, uint8_t is_local);

uint8_t ee_netmsg_selection_copies(uint8_t is_local, uint8_t message_id, uint8_t current_id);

uint8_t ee_netmsg_command_runs(uint8_t is_server,
                               uint8_t message_type,
                               uint8_t message_id,
                               uint8_t last_id);

uint32_t ee_netmsg_selection_passes(uint8_t executing_selection);

/// 0 nothing, 1 add, 2 take.
uint8_t ee_netmsg_add_remove(uint8_t add, uint32_t amount, int64_t have);

int64_t ee_netmsg_trade_price(float rate, int64_t trade, uint8_t buy);

EeNetMsgExchangeStep ee_netmsg_exchange_step(uint8_t is_sell, int64_t price, int64_t have);

/// The resources in `out_resources`; the count.
///
/// # Safety
/// `amounts` points to 7 values, `out_resources` to room for 5.
uint32_t ee_netmsg_tribute_order(const uint32_t *amounts, uint8_t text, uint8_t *out_resources);

uint8_t ee_netmsg_tribute_viewer(uint8_t local_is_from, uint8_t local_is_to);

/// 1 and the fraction in `out_fraction` when disbanded; 0 (`out_fraction` untouched) else.
///
/// # Safety
/// `out_fraction` is writable.
uint8_t ee_netmsg_disband_refund(int64_t hit_points,
                                 int64_t max_hit_points,
                                 uint8_t can_disband,
                                 float *out_fraction);

/// `ExportSize` of a class whose members are all fixed (its constant); 0 for a class with variable members.
uint32_t ee_netmsg_fixed_size(uint32_t class_id);

/// `ExportSize`: the wire size of the message these slots describe.
///
/// # Safety
/// `slots` points to `count` slots filled as the module comment says.
uint32_t ee_netmsg_export_size(uint32_t class_id, const EeNetMsgSlot *slots, size_t count);

/// `ExportMessage`: writes the message into `out` (`out_size` bytes, from `ee_netmsg_export_size`); returns the bytes
/// written.
///
/// # Safety
/// `slots` as for `ee_netmsg_export_size`; `out` holds `out_size` bytes.
uint32_t ee_netmsg_export(uint32_t class_id,
                          const EeNetMsgSlot *slots,
                          size_t count,
                          uint8_t *out,
                          size_t out_size);

/// `ImportMessage`: reads the header and the members the class's import reads from `data`.
///
/// # Safety
/// `data` holds a whole message of this class; `slots` points to `count` slots whose fixed members are writable.
void ee_netmsg_import(uint32_t class_id,
                      const uint8_t *data,
                      EeNetMsgSlot *slots,
                      size_t count);

/// How a class's member `index` (after the header) travels: `EE_NETMSG_FIELD_*` (NONE past the last member), so a
/// reader of the slots (the capture's member records) knows what each slot holds.
uint8_t ee_netmsg_field_kind(uint32_t class_id,
                             uint32_t index);

/// How many members (after the header) a class's import reads: all of them but for `EEMChangeFormation`.
uint32_t ee_netmsg_import_fields(uint32_t class_id);

/// The class the game's or the engine's factory builds for message type `message_type`, or `u32::MAX`.
uint32_t ee_netmsg_class_of_type(uint8_t message_type);

/// The message kind of a type: engine, game, or none. A message object is an `EEMessage` exactly when its type is a
/// game type: every class's constructor passes its type, and the import constructors take the type the factory
/// dispatched on.
uint8_t ee_netmsg_message_kind(uint8_t message_type);

/// `NEMPlayerInput::ExportSize`: the count byte and the travelling inputs' sizes (`inputs`: one slot per input of
/// the list, its `size` its `ExportSize`).
///
/// # Safety
/// `inputs` points to `count` slots.
uint32_t ee_netmsg_inputs_size(const EeNetMsgSlot *inputs,
                               size_t count);

/// `NEMPlayerInput::ExportMessage`: the count byte and the travelling inputs' bytes into `out` (`out_size` bytes);
/// returns the bytes written.
///
/// # Safety
/// `inputs` points to `count` slots, each with its exported bytes; `out` holds `out_size` bytes.
uint32_t ee_netmsg_inputs_export(const EeNetMsgSlot *inputs,
                                 size_t count,
                                 uint8_t *out,
                                 size_t out_size);

/// `NEMPlayerInput::ImportMessage`: reads the count byte at `data` and has `build` make each input in turn
/// (`codec::walk_inputs`); returns the offset after the last input built.
///
/// # Safety
/// `data` holds a received inputs list; `build` is safe to call with `context` and a pointer into it.
uint32_t ee_netmsg_inputs_import(const uint8_t *data,
                                 EeNetMsgBuildInput build,
                                 void *context);

/// `CompressUnits`: packs `count` ids for `owner` into `out` (256 bytes); returns the byte count.
///
/// # Safety
/// `ids` holds `count` values; `out` 256 bytes.
uint8_t ee_netmsg_compress_units(const uint32_t *ids, size_t count, uint32_t owner, uint8_t *out);

/// `DecompressUnits`: the ids of a buffer (256 bytes, `size` of them used) into `out` (room for `capacity`, at least
/// `units::MAX_BUFFER`); returns how many.
///
/// # Safety
/// `buffer` holds 256 bytes; `out` `capacity` values.
size_t ee_netmsg_decompress_units(const uint8_t *buffer,
                                  uint8_t size,
                                  int32_t *out,
                                  size_t capacity);

/// What an engine message type is: its codec class, member counts, record size, flags, send-to-all-and-wait member,
/// response rule, label (`class_id` = `u32::MAX` for a type the engine does not build).
EeNetMsgNeType ee_netmsg_ne_type(uint8_t message_type);

/// Member `index` (0 = the first after the header) of an engine type's record; NONE past the last.
EeNetMsgNeField ee_netmsg_ne_field(uint8_t message_type, uint32_t index);

/// Registers `builder` (NULL: none) for the types `first..=last` (`NEMessage::RegisterKnownMessages` 0x20..0x3c,
/// `EEMessage::RegisterKnownMessages` 0x41..0xfd).
void ee_netmsg_register_builder(uint8_t first,
                                uint8_t last,
                                void *(*builder)(uint8_t *data));

/// `NEMessage::ConvertMemoryToMessage`: the message the builder registered for the type at `data[1]` makes, or NULL
/// when no builder is registered for it.
///
/// # Safety
/// `data` holds a received message; the registered builder is safe to call with it.
void *ee_netmsg_build(uint8_t *data);

/// The codec class of a record message type, or `u32::MAX` for a type with a class of its own (or none).
uint32_t ee_netmsg_record_class(uint8_t message_type);

/// A record type's flags (`EE_NETMSG_RECORD_PAUSED`, `EE_NETMSG_RECORD_WHEN_OUT`); 0 for any other type.
uint8_t ee_netmsg_record_flags(uint8_t message_type);

/// A record type's debug label (`GetMessageLabel`), a static C string; "" for any other type.
const char *ee_netmsg_record_label(uint8_t message_type);

/// Member `index` of a record class (1 = the first after the selection id; NONE past the last).
EeNetMsgRecordField ee_netmsg_record_field(uint32_t class_id, uint32_t index);

/// Member `index` of a record type: the wire's, then the members that are not on the wire (NONE past the last).
EeNetMsgRecordField ee_netmsg_record_member(uint8_t message_type,
                                            uint32_t index);

/// A record type's rules (all 0 for any other type).
EeNetMsgRecordRules ee_netmsg_record_rules(uint8_t message_type);

/// The sweep shape of a game message type (its codec class's layout; all 0 for no game type).
EeNetMsgSweepShape ee_netmsg_sweep_shape(uint8_t message_type);

/// The sweep shape of an engine message type (its codec class's layout).
EeNetMsgEngineSweepShape ee_netmsg_engine_sweep_shape(uint8_t message_type);

/// The C ABI: a server's (`server`) or client's member `what` over the C++ host, with the forwarder's frame.
///
/// # Safety
/// `host` is the C++ host and `frame` its frame; a message argument is a live message; the laggers' slots are
/// `b` bytes at `a`.
int64_t ee_netmsg_session(EeNetSessHostFn host,
                          void *frame,
                          bool server,
                          uint32_t what,
                          int64_t a,
                          int64_t b,
                          int64_t c,
                          int64_t d);

}  // extern "C"

#endif  // EE_RUST_SIM_NETMSG_H
